/* ============================== BACKEND (Supabase + localStorage) ==============================
   "shared" data (the marketplace: users, jobs, matches, chats, reviews, etc.) lives in Supabase,
   so every visitor sees the same data. "personal" data (just the session token) lives in
   localStorage, since it only needs to exist on this device.

   SETUP REQUIRED — see README.md. In short:
   1. Create a free project at https://supabase.com
   2. Run the SQL in README.md against it (creates one table: kiver_kv)
   3. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY (see .env.example)
============================================================================================= */
import { createClient } from "@supabase/supabase-js";

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_ANON_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY;
const SUPABASE_CONFIGURED = !!(SUPABASE_URL && SUPABASE_ANON_KEY);

const supabase = SUPABASE_CONFIGURED ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) : null;

async function sGet(key, shared = false) {
  try {
    if (!shared) return localStorage.getItem(key);
    if (!supabase) return null;
    const { data, error } = await supabase.from("kiver_kv").select("value").eq("key", key).maybeSingle();
    if (error || !data) return null;
    return data.value;
  } catch (e) { return null; }
}
async function sSet(key, value, shared = false) {
  try {
    const str = JSON.stringify(value);
    if (!shared) { localStorage.setItem(key, str); return true; }
    if (!supabase) return false;
    const { error } = await supabase.from("kiver_kv").upsert({ key, value: str, updated_at: new Date().toISOString() });
    if (error) { console.error("storage set failed", key, error); return false; }
    return true;
  } catch (e) { console.error("storage set failed", key, e); return false; }
}
async function getJSON(key, shared, fallback) {
  const v = await sGet(key, shared);
  if (v === null || v === undefined) return fallback;
  try { return JSON.parse(v); } catch { return fallback; }
}
async function addToList(listKey, id) {
  const list = await getJSON(listKey, true, []);
  if (!list.includes(id)) { list.push(id); await sSet(listKey, list, true); }
  return list;
}
function uid() {
  return (crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2));
}
function todayStr() { return new Date().toISOString().slice(0, 10); }

