function ProfessionPicker({ selected, onChange, max = 3, placeholder = "Type a job or skill..." }) {
  const [query, setQuery] = useState("");
  const q = query.trim().toLowerCase();
  const suggestions = q
    ? PROFESSION_SUGGESTIONS.filter(p => p.toLowerCase().startsWith(q) && !selected.includes(p)).slice(0, 6)
    : [];

  function addItem(text) {
    const clean = capWords(text.trim());
    if (!clean || selected.length >= max || selected.some(s => s.toLowerCase() === clean.toLowerCase())) return;
    onChange([...selected, clean]);
    setQuery("");
  }
  function removeItem(item) {
    onChange(selected.filter(s => s !== item));
  }

  return (
    <div>
      {selected.length > 0 && (
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
          {selected.map((s, i) => (
            <span key={i} style={{
              display: "flex", alignItems: "center", gap: 5, background: C.blueSoft, color: C.blue,
              borderRadius: 20, padding: "5px 10px 5px 12px", fontSize: 12.5, fontWeight: 700
            }}>
              {s}
              <button type="button" onClick={() => removeItem(s)} style={{ background: "none", border: "none", padding: 0, display: "flex", color: C.blue }}>
                <IconX size={12} />
              </button>
            </span>
          ))}
        </div>
      )}
      {selected.length < max ? (
        <div style={{ position: "relative" }}>
          <input
            style={inputStyle}
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={e => { if (e.key === "Enter") { e.preventDefault(); addItem(query); } }}
            placeholder={placeholder}
          />
          {suggestions.length > 0 && (
            <div style={{
              position: "absolute", top: "100%", left: 0, right: 0, background: "#fff", border: `1px solid ${C.line}`,
              borderRadius: 10, marginTop: 4, boxShadow: "0 10px 24px #13204322", zIndex: 5, overflow: "hidden"
            }}>
              {suggestions.map((s, i) => (
                <button key={i} type="button" onClick={() => addItem(s)} style={{
                  display: "block", width: "100%", textAlign: "left", padding: "9px 12px", background: "none", border: "none",
                  fontSize: 13.5, color: C.ink, borderBottom: i < suggestions.length - 1 ? `1px solid ${C.line}` : "none"
                }}>{s}</button>
              ))}
            </div>
          )}
        </div>
      ) : max > 1 ? (
        <div style={{ fontSize: 11.5, color: C.inkDim }}>Maximum {max} selected.</div>
      ) : null}
    </div>
  );
}

function PromptsPicker({ prompts, onChange, max = 2 }) {
  const slots = prompts.length ? prompts : [{ prompt: "", answer: "" }];

  function updateSlot(i, field, value) {
    const next = slots.map((s, idx) => idx === i ? { ...s, [field]: value } : s);
    onChange(next);
  }
  function addSlot() {
    if (slots.length >= max) return;
    onChange([...slots, { prompt: "", answer: "" }]);
  }
  function removeSlot(i) {
    onChange(slots.filter((_, idx) => idx !== i));
  }

  return (
    <div style={{ marginBottom: 14 }}>
      {slots.map((s, i) => (
        <div key={i} style={{ marginBottom: 10, background: C.blueSoft, borderRadius: 12, padding: 12 }}>
          <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8 }}>
            <select value={s.prompt} onChange={e => updateSlot(i, "prompt", e.target.value)} style={{ ...inputStyle, flex: 1, padding: "8px 10px", fontSize: 12.5 }}>
              <option value="">Choose a prompt...</option>
              {PROMPT_LIBRARY.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
            {slots.length > 1 && (
              <button type="button" onClick={() => removeSlot(i)} style={{ background: "#fff", border: "none", borderRadius: "50%", width: 26, height: 26, display: "flex", alignItems: "center", justifyContent: "center", color: C.inkDim, flexShrink: 0 }}>
                <IconX size={12} />
              </button>
            )}
          </div>
          <input value={s.answer} onChange={e => updateSlot(i, "answer", e.target.value)} placeholder="Your answer..." style={{ ...inputStyle, fontSize: 13 }} />
        </div>
      ))}
      {slots.length < max && (
        <button type="button" onClick={addSlot} style={{ background: "none", border: `1.5px dashed ${C.line}`, borderRadius: 10, padding: "9px 12px", fontSize: 12.5, fontWeight: 700, color: C.blue, width: "100%" }}>
          + Add another prompt
        </button>
      )}
    </div>
  );
}

