/* ============================== APP ============================== */
export default function KiverApp() {
  const [booted, setBooted] = useState(false);
  const [splash, setSplash] = useState(true);
  const [session, setSession] = useState(null);
  const [me, setMe] = useState(null);
  const [view, setView] = useState("landing");
  const [tab, setTab] = useState("discover");
  const [afterVerify, setAfterVerify] = useState("app");

  useEffect(() => {
    const t = setTimeout(() => setSplash(false), 1300);
    (async () => {
      const s = await getJSON("kiver:session", false, null);
      if (s && s.userId) {
        const u = await getJSON("kiver:user:" + s.userId, true, null);
        if (u) {
          setSession(s); setMe(u);
          if (!u.emailVerified) { setAfterVerify("app"); setView("verifyemail"); }
          else setView("app");
        }
      }
      setBooted(true);
    })();
    return () => clearTimeout(t);
  }, []);

  async function refreshMe(userId) {
    const u = await getJSON("kiver:user:" + userId, true, null);
    setMe(u);
    return u;
  }
  async function startSession(user) {
    setMe(user);
    const s = { userId: user.id };
    await sSet("kiver:session", s, false);
    setSession(s);
  }
  async function logout() {
    await sSet("kiver:session", {}, false);
    setSession(null); setMe(null); setView("landing"); setTab("discover");
  }

  // Create a brand-new account: registers auth, grants founding-member premium to the first 50 signups.
  async function createAccount(user, email, password) {
    const signupCount = (await getJSON("kiver:signup-count", true, 0)) + 1;
    await sSet("kiver:signup-count", signupCount, true);

    const isFounding = signupCount <= FOUNDING_MEMBER_LIMIT;
    const finalUser = {
      ...user,
      email,
      emailVerified: false,
      isFoundingMember: isFounding,
      premium: isFounding ? true : !!user.premium,
      premiumExpiresAt: isFounding ? Date.now() + YEAR_MS : null,
    };

    await sSet("kiver:user:" + finalUser.id, finalUser, true);
    await addToList("kiver:user-ids", finalUser.id);
    await sSet("kiver:auth-email:" + email.trim().toLowerCase(), { userId: finalUser.id, passwordObf: obfuscate(password) }, true);
    await sSet("kiver:verify:" + finalUser.id, { code: generateCode(), createdAt: Date.now() }, true);

    await startSession(finalUser);
    setAfterVerify(finalUser.type === "employer" ? "postjob" : "app");
    setView("verifyemail");
  }

  async function loginWithUser(user) {
    await startSession(user);
    if (!user.emailVerified) {
      await sSet("kiver:verify:" + user.id, { code: generateCode(), createdAt: Date.now() }, true);
      setAfterVerify("app");
      setView("verifyemail");
    } else {
      setView("app"); setTab("discover");
    }
  }

  async function handleVerified() {
    const updated = { ...me, emailVerified: true };
    await sSet("kiver:user:" + me.id, updated, true);
    setMe(updated);
    setView(afterVerify);
    if (afterVerify === "app") setTab("discover");
  }

  if (splash || !booted) return <Splash />;

  if (!SUPABASE_CONFIGURED) {
    return (
      <div style={{
        minHeight: 580, maxWidth: 440, margin: "0 auto", background: "#fff", borderRadius: 20,
        padding: 28, fontFamily: "sans-serif", color: "#132043", boxShadow: "0 0 0 1px #E4EBFA"
      }}>
        <div style={{ fontWeight: 800, fontSize: 20, marginBottom: 10 }}>Kiver isn't connected to a database yet</div>
        <p style={{ fontSize: 14, lineHeight: 1.6, color: "#75839E" }}>
          This app stores its data in Supabase. Add <code>VITE_SUPABASE_URL</code> and{" "}
          <code>VITE_SUPABASE_ANON_KEY</code> to your environment (a <code>.env</code> file locally,
          or the Environment Variables panel on Vercel), then redeploy. See README.md for the exact
          setup steps and the SQL needed to create the table.
        </p>
      </div>
    );
  }

  return (
    <div style={{
      height: "100dvh", maxHeight: 800, background: C.bg, color: C.ink, maxWidth: 440, margin: "0 auto",
      borderRadius: 20, overflow: "hidden", position: "relative", display: "flex", flexDirection: "column",
      fontSize: 15, boxShadow: "0 0 0 1px #E4EBFA, 0 20px 60px #0B6EFC1a"
    }}>
      <style>{FONTS}</style>

      {view === "landing" && <Landing onStart={() => setView("authgate")} />}

      {view === "authgate" && (
        <AuthGate
          onBack={() => setView("landing")}
          onChooseSignup={() => setView("auth")}
          onChooseLogin={() => setView("login")}
        />
      )}

      {view === "login" && (
        <LoginForm onBack={() => setView("authgate")} onSuccess={loginWithUser} onForgotPassword={() => setView("forgotpassword")} />
      )}

      {view === "forgotpassword" && (
        <ForgotPasswordForm onBack={() => setView("login")} onDone={() => setView("login")} />
      )}

      {view === "auth" && (
        <AuthFlow
          onBack={() => setView("authgate")}
          onDone={(user, email, password) => createAccount(user, email, password)}
        />
      )}

      {view === "verifyemail" && me && (
        <VerifyEmailScreen me={me} onVerified={handleVerified} onLogout={logout} />
      )}

      {view === "postjob" && me && (
        <PostJobScreen
          employer={me}
          onDone={() => { setView("app"); setTab("discover"); }}
          onSkip={() => { setView("app"); setTab("discover"); }}
        />
      )}

      {view === "app" && me && (
        <AppShell me={me} tab={tab} setTab={setTab} refreshMe={refreshMe} logout={logout} />
      )}

      <ToastHost />
    </div>
  );
}

