function LoginForm({ onBack, onSuccess, onForgotPassword }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function submit() {
    if (!email.trim() || !password) return setError("Enter your email and password.");
    setError(""); setLoading(true);
    const rec = await getJSON("kiver:auth-email:" + email.trim().toLowerCase(), true, null);
    if (!rec || rec.passwordObf !== obfuscate(password)) {
      setLoading(false);
      return setError("Incorrect email or password.");
    }
    const user = await getJSON("kiver:user:" + rec.userId, true, null);
    setLoading(false);
    if (!user) return setError("We couldn't find that account.");
    onSuccess(user);
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", minHeight: 580 }}>
      <TopBar title="Log In" onBack={onBack} />
      <div style={{ padding: 20 }} className="fadeup">
        <Field label="Email"><input style={inputStyle} type="email" value={email} onChange={e => setEmail(e.target.value.toLowerCase())} placeholder="you@example.com" /></Field>
        <Field label="Password"><input style={inputStyle} type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="••••••••" /></Field>
        <button onClick={onForgotPassword} style={{ background: "none", border: "none", color: C.blue, fontSize: 13, fontWeight: 600, padding: 0, marginBottom: 16 }}>
          Forgot password?
        </button>
        {error && <div style={{ color: "#E14B5A", fontSize: 13, marginBottom: 10 }}>{error}</div>}
        <PrimaryBtn onClick={submit} disabled={loading}>{loading ? "Logging in..." : "Log In"}</PrimaryBtn>
      </div>
    </div>
  );
}

function ForgotPasswordForm({ onBack, onDone }) {
  const [step, setStep] = useState("email"); // email | reset | done
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function findAccount() {
    if (!email.trim()) return setError("Enter the email on your account.");
    setLoading(true);
    const key = "kiver:auth-email:" + email.trim().toLowerCase();
    const rec = await getJSON(key, true, null);
    setLoading(false);
    if (!rec) return setError("No account found with that email.");
    setError("");
    setStep("reset");
  }

  async function resetPassword() {
    if (password.length < 4) return setError("Password should be at least 4 characters.");
    if (password !== confirm) return setError("Passwords don't match.");
    setLoading(true);
    const key = "kiver:auth-email:" + email.trim().toLowerCase();
    const rec = await getJSON(key, true, null);
    if (!rec) { setLoading(false); return setError("That account can't be found anymore."); }
    await sSet(key, { ...rec, passwordObf: obfuscate(password) }, true);
    setLoading(false);
    setError("");
    setStep("done");
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", minHeight: 580 }}>
      <TopBar title="Reset Password" onBack={onBack} />
      <div style={{ padding: 20 }} className="fadeup">
        {step === "email" && (
          <>
            <p style={{ color: C.inkDim, fontSize: 13.5, marginBottom: 16, lineHeight: 1.5 }}>
              Enter the email on your account. In this preview, we'll reset it right here instead of emailing a link.
            </p>
            <Field label="Email"><input style={inputStyle} type="email" value={email} onChange={e => setEmail(e.target.value.toLowerCase())} placeholder="you@example.com" /></Field>
            {error && <div style={{ color: "#E14B5A", fontSize: 13, marginBottom: 10 }}>{error}</div>}
            <PrimaryBtn onClick={findAccount} disabled={loading}>{loading ? "Checking..." : "Continue"}</PrimaryBtn>
          </>
        )}
        {step === "reset" && (
          <>
            <p style={{ color: C.inkDim, fontSize: 13.5, marginBottom: 16 }}>Choose a new password for {email}.</p>
            <Field label="New password"><input style={inputStyle} type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="••••••••" /></Field>
            <Field label="Confirm password"><input style={inputStyle} type="password" value={confirm} onChange={e => setConfirm(e.target.value)} placeholder="••••••••" /></Field>
            {error && <div style={{ color: "#E14B5A", fontSize: 13, marginBottom: 10 }}>{error}</div>}
            <PrimaryBtn onClick={resetPassword} disabled={loading}>{loading ? "Saving..." : "Reset Password"}</PrimaryBtn>
          </>
        )}
        {step === "done" && (
          <div style={{ textAlign: "center", marginTop: 30 }}>
            <div style={{ width: 60, height: 60, borderRadius: "50%", background: "#E4F9EF", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px" }}>
              <Check size={26} color={C.good} strokeWidth={3} />
            </div>
            <div className="disp" style={{ fontWeight: 700, fontSize: 18, marginBottom: 8 }}>Password updated</div>
            <p style={{ color: C.inkDim, fontSize: 13.5, marginBottom: 20 }}>You can log in with your new password now.</p>
            <PrimaryBtn onClick={onDone}>Back to Log In</PrimaryBtn>
          </div>
        )}
      </div>
    </div>
  );
}

/* ============================== EMAIL VERIFICATION ============================== */
function VerifyEmailScreen({ me, onVerified, onLogout }) {
  const [code, setCode] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [resent, setResent] = useState(false);
  const [fallbackCode, setFallbackCode] = useState(null); // only shown if real email delivery failed
  const [sendReason, setSendReason] = useState(""); // the actual reason it failed, from the server
  const [sendStatus, setSendStatus] = useState("sending"); // sending | sent | failed

  async function sendCode(rec) {
    setSendStatus("sending");
    try {
      const r = await fetch("/api/send-verification", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: me.email, code: rec.code }),
      });
      if (r.ok) { setSendStatus("sent"); setFallbackCode(null); setSendReason(""); return; }
      const body = await r.json().catch(() => ({}));
      throw new Error(body.error || `Send failed (HTTP ${r.status})`);
    } catch (e) {
      // Real email delivery failed — fall back to showing the code on screen so the app
      // never dead-ends, but show the ACTUAL reason rather than guessing.
      setSendStatus("failed");
      setSendReason(e.message || "Unknown error");
      setFallbackCode(rec.code);
    }
  }

  useEffect(() => {
    (async () => {
      let rec = await getJSON("kiver:verify:" + me.id, true, null);
      if (!rec) {
        rec = { code: generateCode(), createdAt: Date.now() };
        await sSet("kiver:verify:" + me.id, rec, true);
      }
      sendCode(rec);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [me.id]);

  async function verify() {
    if (code.trim().length < 4) return setError("Enter the code sent to your email.");
    setLoading(true);
    const rec = await getJSON("kiver:verify:" + me.id, true, null);
    setLoading(false);
    if (!rec || rec.code !== code.trim()) return setError("That code doesn't match. Try again.");
    setError("");
    onVerified();
  }

  async function resend() {
    const rec = { code: generateCode(), createdAt: Date.now() };
    await sSet("kiver:verify:" + me.id, rec, true);
    await sendCode(rec);
    setResent(true);
    setTimeout(() => setResent(false), 2500);
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", minHeight: 580 }}>
      <TopBar title="Verify Your Email" />
      <div style={{ padding: 20, flex: 1 }} className="fadeup">
        <div style={{ width: 56, height: 56, borderRadius: "50%", background: C.blueSoft, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 16 }}>
          <Mail size={24} color={C.blue} />
        </div>
        <p style={{ color: C.inkDim, fontSize: 14, lineHeight: 1.5, marginBottom: 6 }}>
          {sendStatus === "sending" && "Sending a 6-digit code to "}
          {sendStatus === "sent" && "We've sent a 6-digit code to "}
          {sendStatus === "failed" && "We tried to send a 6-digit code to "}
          <strong style={{ color: C.ink }}>{me.email}</strong>. Enter it below — you'll need to verify before you can use Kiver.
        </p>
        {fallbackCode && (
          <div style={{ background: "#FFF4D6", color: C.goldDark, fontSize: 12.5, borderRadius: 10, padding: "9px 12px", marginTop: 10, marginBottom: 16, lineHeight: 1.4 }}>
            Email delivery failed: <strong>{sendReason}</strong>
            <br />So here's your code instead: <strong>{fallbackCode}</strong>.
          </div>
        )}
        <Field label="Verification code">
          <input style={{ ...inputStyle, fontSize: 20, letterSpacing: "0.3em", textAlign: "center" }}
            maxLength={6} inputMode="numeric" value={code} onChange={e => setCode(e.target.value.replace(/\D/g, ""))} placeholder="000000" />
        </Field>
        {error && <div style={{ color: "#E14B5A", fontSize: 13, marginBottom: 10 }}>{error}</div>}
        <PrimaryBtn onClick={verify} disabled={loading}>{loading ? "Verifying..." : "Verify Email"}</PrimaryBtn>
        <button onClick={resend} style={{ background: "none", border: "none", color: C.blue, fontSize: 13, fontWeight: 600, marginTop: 16, padding: 0 }}>
          {resent ? "New code sent!" : "Resend code"}
        </button>
        <div style={{ marginTop: 30, borderTop: `1px solid ${C.line}`, paddingTop: 16 }}>
          <button onClick={onLogout} style={{ background: "none", border: "none", color: C.inkDim, fontSize: 13, fontWeight: 600 }}>
            Log out and use a different account
          </button>
        </div>
      </div>
    </div>
  );
}

/* ============================== AUTH FLOW (create account) ============================== */
function AuthFlow({ onBack, onDone }) {
  const [step, setStep] = useState("role");
  const [saving, setSaving] = useState(false);

  return (
    <div style={{ display: "flex", flexDirection: "column", minHeight: 580 }}>
      <TopBar title="Create Account" onBack={onBack} />
      <div style={{ padding: 20, overflowY: "auto", flex: 1 }}>
        {step === "role" && (
          <div className="fadeup">
            <p style={{ color: C.inkDim, marginBottom: 18 }}>Are you looking for work, or looking to hire?</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <RoleCard icon={<Briefcase size={22} color={C.blue} />} title="I'm a Worker" desc="Find real work near you or abroad." onClick={() => setStep("worker")} />
              <RoleCard icon={<User size={22} color={C.blue} />} title="I'm an Employer" desc="Post a job, find someone today." onClick={() => setStep("employer")} />
            </div>
          </div>
        )}
        {step === "worker" && (
          <WorkerForm saving={saving}
            onBack={() => setStep("role")}
            onSubmit={async (data) => {
              setSaving(true);
              const { email, password, ...profile } = data;
              const user = { id: uid(), type: "worker", createdAt: Date.now(), swipeCredits: { date: todayStr(), used: 0 }, dailySwipes: { date: todayStr(), count: 0 }, ...profile };
              await onDone(user, email, password);
              setSaving(false);
            }} />
        )}
        {step === "employer" && (
          <EmployerForm saving={saving}
            onBack={() => setStep("role")}
            onSubmit={async (data) => {
              setSaving(true);
              const { email, password, ...profile } = data;
              const user = { id: uid(), type: "employer", createdAt: Date.now(), premium: false, swipeCredits: { date: todayStr(), used: 0 }, dailySwipes: { date: todayStr(), count: 0 }, ...profile };
              await onDone(user, email, password);
              setSaving(false);
            }} />
        )}
      </div>
    </div>
  );
}

