/* ============================== POST JOB ============================== */
function PostJobScreen({ employer, onDone, onSkip, isEdit, existing }) {
  const [photos, setPhotos] = useState(existing?.photos || []);
  const [titleArr, setTitleArr] = useState(existing?.title ? [existing.title === "Custom" ? existing.customTitle : existing.title] : []);
  const [city, setCity] = useState(existing?.city || "");
  const [country, setCountry] = useState(existing?.country || "");
  const [pay, setPay] = useState((existing?.pay || "").replace(/^\$\s*/, ""));
  const [desc, setDesc] = useState(existing?.description || "");
  const [sponsorship, setSponsorship] = useState(existing?.sponsorship || "Not specified");
  const [tagsInput, setTagsInput] = useState((existing?.tags || []).join(", "));
  const [slots, setSlots] = useState(existing?.slots || 1);
  const [lat, setLat] = useState(existing?.lat ?? null);
  const [lng, setLng] = useState(existing?.lng ?? null);
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);

  async function submit() {
    if (photos.length < 1) return setError("Upload at least 1 workplace photo.");
    if (titleArr.length === 0) return setError("Enter a job title.");
    if (!city.trim() || !country.trim()) return setError("Location is required.");
    if (!pay.trim()) return setError("Pay and hours are required.");
    setError(""); setSaving(true);
    const job = {
      id: existing?.id || uid(),
      employerId: employer.id,
      photos, title: titleArr[0], customTitle: "",
      city, country, location: `${city}, ${country}`, lat, lng,
      pay: "$" + pay.trim().replace(/^\$\s*/, ""), description: desc, sponsorship,
      tags: tagsInput.split(",").map(t => t.trim()).filter(Boolean),
      slots: Math.max(1, parseInt(slots, 10) || 1),
      urgent: existing?.urgent || false,
      urgentUntil: existing?.urgentUntil || null,
      createdAt: existing?.createdAt || Date.now(),
    };
    await sSet("kiver:job:" + job.id, job, true);
    await addToList("kiver:job-ids", job.id);
    await addToList("kiver:employer-jobs:" + employer.id, job.id);
    setSaving(false);
    toast(isEdit ? "✓ Job updated" : "✓ Job posted");
    onDone(job);
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", minHeight: 580 }}>
      <TopBar title={isEdit ? "Edit job" : "Post a job"} onBack={isEdit ? onDone : undefined}
        right={!isEdit && <button onClick={onSkip} style={{ background: "none", border: "none", color: C.inkDim, fontSize: 13 }}>Skip for now</button>} />
      <div style={{ padding: 20, overflowY: "auto", flex: 1 }}>
        <PhotoArrayPicker photos={photos} onChange={setPhotos} max={3} label="Workplace photos" required />

        <Field label="Job title *">
          <ProfessionPicker selected={titleArr} onChange={setTitleArr} max={1} placeholder="Start typing, e.g. Gardener, IT Technician..." />
        </Field>

        <div style={{ display: "flex", gap: 10 }}>
          <div style={{ flex: 1 }}><Field label="City *"><input style={inputStyle} value={city} onChange={e => setCity(capWords(e.target.value))} placeholder="Lisbon" /></Field></div>
          <div style={{ flex: 1 }}><Field label="Country *"><input style={inputStyle} value={country} onChange={e => setCountry(capWords(e.target.value))} placeholder="Portugal" /></Field></div>
        </div>
        <LocationCaptureButton lat={lat} lng={lng} onCapture={(la, lo) => { setLat(la); setLng(lo); }} label="Use my current location as the worksite" />

        <div style={{ display: "flex", gap: 10 }}>
          <div style={{ flex: 2 }}>
            <Field label="Pay & hours *">
              <div style={{ display: "flex", alignItems: "center", border: `1.5px solid ${C.line}`, borderRadius: 10, background: C.bg2 }}>
                <span style={{ color: C.inkDim, fontWeight: 700, paddingLeft: 13 }}>$</span>
                <input style={{ ...inputStyle, border: "none", background: "transparent", padding: "12px 13px 12px 4px" }}
                  value={pay} onChange={e => setPay(e.target.value)} placeholder="18/hr, 6 days a week" />
              </div>
            </Field>
          </div>
          <div style={{ flex: 1 }}>
            <Field label="Positions">
              <input style={inputStyle} type="number" min="1" value={slots} onChange={e => setSlots(e.target.value)} />
            </Field>
          </div>
        </div>
        {Number(slots) > 1 && (
          <div style={{ color: C.inkDim, fontSize: 12, marginTop: -8, marginBottom: 14 }}>
            Hiring in bulk — you can swipe multiple workers for this job until all {slots} spots are filled.
          </div>
        )}

        <Field label="Description"><textarea style={{ ...inputStyle, minHeight: 70, resize: "vertical" }} value={desc} onChange={e => setDesc(e.target.value)} placeholder="What's the work actually like?" /></Field>
        <Field label="Sponsorship offered">
          <select style={inputStyle} value={sponsorship} onChange={e => setSponsorship(e.target.value)}>
            <option>Yes</option><option>No</option><option>Not specified</option>
          </select>
        </Field>
        <Field label="Tags (comma separated)"><input style={inputStyle} value={tagsInput} onChange={e => setTagsInput(e.target.value)} placeholder="Same-day pay, No CV needed" /></Field>

        {error && <div style={{ color: "#E14B5A", fontSize: 13, marginBottom: 10 }}>{error}</div>}
        <PrimaryBtn onClick={submit} disabled={saving}>{saving ? "Saving..." : isEdit ? "Save changes" : "Post job"}</PrimaryBtn>
      </div>
    </div>
  );
}

