/* ============================== SWIPE CARD (draggable) ============================== */
const labelBaseStyle = {
  position: "absolute", top: 26, padding: "7px 14px", borderRadius: 10, border: "3.5px solid",
  fontWeight: 900, fontSize: 24, letterSpacing: "0.04em", zIndex: 5, pointerEvents: "none",
  fontFamily: "'Poppins', sans-serif", background: "#FFFFFFcc", backdropFilter: "blur(2px)"
};

function SwipeCard({ data, isWorker, trigger, onExitComplete, me, onBlock, onReport }) {
  const [pos, setPos] = useState({ x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);
  const [exiting, setExiting] = useState(null);
  const startRef = useRef({ x: 0, y: 0 });
  const posRef = useRef({ x: 0, y: 0 });
  const cardRef = useRef();

  useEffect(() => {
    if (trigger) doExit(trigger.dir);
    // eslint-disable-next-line
  }, [trigger && trigger.nonce]);

  function doExit(dir) {
    if (exiting) return;
    setExiting(dir);
    setDragging(false);
    const targetX = dir === "right" ? 640 : -640;
    setPos({ x: targetX, y: posRef.current.y - 30 });
    setTimeout(() => onExitComplete(dir), 260);
  }

  function onPointerDown(e) {
    if (exiting) return;
    setDragging(true);
    startRef.current = { x: e.clientX - posRef.current.x, y: e.clientY - posRef.current.y };
    cardRef.current?.setPointerCapture?.(e.pointerId);
  }
  function onPointerMove(e) {
    if (!dragging) return;
    const next = { x: e.clientX - startRef.current.x, y: e.clientY - startRef.current.y };
    posRef.current = next;
    setPos(next);
  }
  function onPointerUp() {
    if (!dragging) return;
    setDragging(false);
    if (Math.abs(posRef.current.x) > 110) {
      doExit(posRef.current.x > 0 ? "right" : "left");
    } else {
      posRef.current = { x: 0, y: 0 };
      setPos({ x: 0, y: 0 });
    }
  }

  const rot = pos.x / 16;
  const dragLike = Math.min(Math.max(pos.x / 100, 0), 1);
  const dragNope = Math.min(Math.max(-pos.x / 100, 0), 1);
  const likeOpacity = exiting === "right" ? 1 : exiting === "left" ? 0 : dragLike;
  const nopeOpacity = exiting === "left" ? 1 : exiting === "right" ? 0 : dragNope;

  return (
    <div
      ref={cardRef}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      style={{
        position: "absolute", inset: 0,
        transform: `translate(${pos.x}px, ${pos.y}px) rotate(${rot}deg)`,
        transition: dragging ? "none" : "transform 0.32s cubic-bezier(.19,.85,.32,1.15)",
        touchAction: "none", cursor: dragging ? "grabbing" : "grab", zIndex: 3
      }}
    >
      {isWorker ? <JobCard job={data} me={me} onBlock={onBlock} onReport={onReport} /> : <WorkerCard worker={data} me={me} onBlock={onBlock} onReport={onReport} />}
      <div style={{ ...labelBaseStyle, left: 18, borderColor: C.blue, color: C.blue, opacity: likeOpacity, transform: `rotate(-16deg) scale(${0.85 + likeOpacity * 0.15})` }}>LIKE</div>
      <div style={{ ...labelBaseStyle, right: 18, borderColor: C.steelDark, color: C.steelDark, opacity: nopeOpacity, transform: `rotate(16deg) scale(${0.85 + nopeOpacity * 0.15})` }}>NOPE</div>
    </div>
  );
}

function PeekCard({ data, isWorker, depth }) {
  return (
    <div style={{
      position: "absolute", inset: 0, zIndex: 2 - depth,
      transform: `scale(${1 - depth * 0.045}) translateY(${depth * 14}px)`,
      opacity: 1 - depth * 0.25, pointerEvents: "none"
    }}>
      {isWorker ? <JobCard job={data} /> : <WorkerCard worker={data} />}
    </div>
  );
}

